<?php
 namespace Pterodactyl\Http\Controllers\Admin\Dezerx; use Illuminate\View\View; use Illuminate\Http\Request; use Illuminate\Http\RedirectResponse; use Pterodactyl\Models\Nest; use Prologue\Alerts\AlertsMessageBag; use Pterodactyl\Services\Dezerx\Addons; use Pterodactyl\Services\Dezerx\AdminTheme; use Pterodactyl\Services\Dezerx\Drive\GoogleDrive; use Pterodactyl\Http\Controllers\Controller; use Symfony\Component\HttpKernel\Exception\NotFoundHttpException; class AddonsController extends Controller { private const NOTES = [ Addons::ADMIN_THEME => [ 'There is nothing to set up here but the mode. Colours and presets come from <strong>Appearance</strong>, and corner radius, card border, card shadow, field border and font from the <strong>theme editor</strong>, so change them there and the admin area follows on its next page load.', 'With the mode left to each admin, a sun and moon switch sits in the admin top bar. It saves to the same place as the one in the client panel, so whichever side it was flipped on, the other already agrees.', 'Pages added by other extensions pick the theme up wherever they use the stock admin building blocks: boxes, tables, forms, buttons, tabs and alerts. Anything that paints its own colours keeps them.', ], Addons::ADMIN_OVERVIEW => [ 'Everything is drawn on the admin home page, <a href="/admin">Overview</a>, and only administrators can see it or the figures behind it.', 'Usage is sampled by the panel\'s scheduler, so <code>php artisan schedule:run</code> has to be running every minute. Each sample is one request per node to Wings, made side by side with short timeouts, so a node that does not answer shows as unreachable instead of holding up the others. The page itself never contacts a node.', 'Minute samples are kept for two days and hourly ones for ninety, in <code>dezerx_overview_samples</code>. CPU is in cores, where one core is 100% of one thread, against each node\'s thread count as Wings reports it. Bandwidth counts traffic in and out of the servers\' containers; anything a server moved before its last restart and the previous sample is not counted.', ], Addons::SECURITY => [ 'This one guards the sign-up form and nothing else. Somebody who already has an account can still sign in from a VPN, and an administrator can still make accounts by hand, which is the way to let a person in who has been caught by mistake.', 'Addresses are recorded when somebody signs up and again on every sign-in, in <code>dezerx_account_ips</code>. That is how <strong>one account per connection</strong> knows anything, so it only sees accounts that have used the panel since this was switched on. Deleting an account takes its addresses with it.', 'Everything here reads the address the panel thinks the request came from. Behind Cloudflare, a load balancer or an nginx proxy that address is the proxy\'s unless <code>TrustProxies</code> is set up, in which case every visitor looks like the same person and <strong>one account per connection</strong> will refuse the second sign-up you ever get. Check that before switching that one on.', 'Nothing here is a wall. A determined person buys a residential proxy and walks straight through all of it. It is worth switching on because it stops the cheap and lazy version, which is most of it.', ], Addons::PLAYER_MANAGER => [ 'The tab reads the server\'s own files through wings: <code>usercache.json</code>, <code>ops.json</code>, <code>banned-players.json</code>, <code>whitelist.json</code>, the world\'s <code>playerdata</code> and <code>stats</code> folders, and <code>logs/latest.log</code> to work out who is online. Moderation actions are console commands, so the server has to be running for those.', 'Only ever tick eggs that run a <strong>Java Edition</strong> server. On anything else the page will simply find nothing.', ], Addons::PLUGIN_MANAGER => [ 'Browses Modrinth and SpigotMC and has the node download the jar into <code>/plugins</code>. The panel never proxies the file, so the node needs outbound access to those hosts.', 'Tick only <strong>Bukkit-family</strong> eggs: Paper, Purpur, Spigot, Folia, Bungeecord. A Forge or Fabric server has no <code>/plugins</code> folder and the page would write into one nothing reads.', ], Addons::MOD_MANAGER => [ 'The same thing for <code>/mods</code>, over <strong>Modrinth and CurseForge</strong>. SpigotMC is not offered: none of what it hosts belongs in a mods folder. Both sources cover the loaders Modrinth catalogues (Fabric, Forge, NeoForge, Quilt, Babric, BTA Babric, Java Agent, Legacy Fabric, LiteLoader, Risugami\'s ModLoader, NilLoader, Ornithe and Rift), but CurseForge can only <em>filter</em> on Forge, NeoForge, Fabric, Quilt and LiteLoader, so picking one of the other eight sends the browser back to Modrinth.', 'Tick only <strong>mod-loader</strong> eggs. Search results are already filtered to loaders the folder can take, but the folder itself has to be the right one.', ], Addons::DRIVE_BACKUPS => [ 'The panel copies a backup into somebody\'s Drive by streaming it from the node, through the panel, to Google, so this costs the panel bandwidth for the size of every backup taken. The copy runs on the queue, so <code>php artisan queue:work</code> has to be running, and the scheduler (<code>php artisan schedule:run</code>) is what makes the interval happen.', 'Access is asked for with the <code>drive.file</code> scope, which reaches only files this panel created. Connecting an account does not let the panel read anything else in that Drive. Each server keeps its own folder, and only the newest few copies are kept.', ], Addons::SERVER_IMPORTER => [ 'Customers save their own SFTP logins in the tab and those logins are theirs alone, encrypted and never shown to anybody else. What an import may reach and how much it may carry is set on its own page: <a href="/admin/dezerx/importer">Server Importer</a>.', 'An import connects <strong>from the panel</strong> to the host named and writes what it reads onto the customer\'s server through its node, so the transfer costs the panel bandwidth twice over and runs on the queue. The server is stopped before anything is written.', ], Addons::MODPACK_MANAGER => [ 'Searches Modrinth, FTB, ATLauncher, Technic and CurseForge. Installing a pack <strong>kills the server</strong>, downloads several hundred megabytes onto it and unpacks them, and with the wipe option it empties the server root first. The download runs on the queue, so <code>php artisan queue:work</code> has to be running or nothing will arrive.', 'Only CurseForge publishes real server zips that install by unpacking. FTB hands over an installer to run from the console, Modrinth an <code>.mrpack</code> that needs an egg which can resolve a manifest, and Technic almost never publishes a server pack at all.', ], Addons::PALWORLD_MOD_MANAGER => [ 'Browses <strong>CurseForge\'s Palworld section</strong> and has the node download the file straight into the mod folder set on the left. The panel never proxies the download, so the node needs outbound access to CurseForge.', 'Palworld ships mods in two shapes. A loose <code>.pak</code> (with its <code>.ucas</code> and <code>.utoc</code> siblings) belongs in <code>Pal/Content/Paks/~mods</code> and works as soon as it lands. Anything that arrives as a <code>.zip</code> has to be unpacked, which the tab offers as a button on the installed list once the download has finished.', 'CurseForge files Palworld mods under five headings and the tab searches all of them, showing which one each result came from. <strong>Patch Pak Mods</strong> are what the folder above is for. <strong>Lua</strong>, <strong>C++</strong> and <strong>Blueprint</strong> code mods need UE4SS installed on the server and live in its own <code>Mods</code> folder instead, so point the folder there if that is the kind of server you run. It is one panel-wide folder, so a host offering both would set up two eggs.', 'Tick only <strong>Palworld</strong> eggs. On anything else the folder will not exist and the tab has nothing to show.', ], Addons::DAYZ_MOD_MANAGER => [ 'Built for the community <strong>DayZ</strong> egg (pelican-eggs/games-steamcmd). The tab edits two of its startup variables: <code>MODIFICATIONS</code> for client mods (<code>-mod=</code>) and <code>SERVERMODS</code> for server-side ones (<code>-serverMod=</code>). A Workshop mod goes in as <code>@&lt;Workshop ID&gt;</code>, which is the form the egg downloads, updates and copies keys for when the server starts. Changes apply on the next restart.', '<strong>Workshop downloads need a Steam account that owns DayZ.</strong> The server itself installs with any real Steam account, but Steam refuses mod downloads to one that does not own the game. Set the egg\'s Steam username and password defaults to a hosting account that owns DayZ with Steam Guard off, and keep both hidden from users: the panel stores startup variables in plain text. Without such an account, set <em>Disable Mod Downloads/Updates</em> to 1; customers then upload <code>@Mod</code> folders with the file manager and load them from the tab.', 'Searching the Workshop and finding a mod\'s required items use the Steam Web API key below when there is one, and otherwise read Steam\'s public Workshop pages, which works but is slower and breaks if Valve changes their markup. Item details never need a key. Nothing is ever downloaded by the panel.', 'Changing the lists needs the <strong>startup update</strong> permission, since they are startup variables; copying keys needs file create, and deleting a mod folder file delete. If a host locks <code>MODIFICATIONS</code> or <code>SERVERMODS</code> on the egg, the tab shows that list read only. Tick only <strong>DayZ</strong> eggs.', '<strong>Load order.</strong> The egg\'s start script sorts the client mod list (<code>sort -u</code>) before passing it as <code>-mod={{CLIENT_MODS}}</code>, so client mods load in name order whatever order they are listed in, and the tab says so instead of offering arrows. To keep a chosen order, change the egg\'s startup to <code>-mod={{MODIFICATIONS}}</code>: the tab notices and lets the order be set, at the cost of the egg\'s <code>modlist.html</code> support. Server-side mods are never sorted. The script also reads the list unquoted, so a folder with a space in its name ends the list there; the tab flags that.', ], Addons::RUST_WIPE_SCHEDULER => [ 'Wipes run from the panel\'s scheduler (the <code>schedule:run</code> cron Pterodactyl already needs): it warns players with <code>say</code>, stops the server, deletes the save files in <code>server/&lt;identity&gt;</code> through Wings, changes <code>WORLD_SEED</code> or <code>WORLD_SIZE</code> if asked, and starts it again.', 'Tick only <strong>Rust</strong> eggs. Setting up a wipe needs the schedule, file delete, start and stop permissions on the server; a new seed also needs startup update, and only works where the egg lets players edit <code>WORLD_SEED</code>.', ], Addons::RUST_PLUGIN_MANAGER => [ 'Plugins come from <strong>umod.org</strong> only, by name: the panel downloads the <code>.cs</code> and writes it into <code>/oxide/plugins</code>, or <code>/carbon/plugins</code> when the server\'s modding framework is set to Carbon. The panel needs outbound access to umod.org.', 'Tick only <strong>Rust</strong> eggs. A server still set to vanilla has no plugin folder until Oxide or Carbon is chosen on its Startup page and it has been restarted once.', ], Addons::AUTO_ACTION => [ 'The due date is carried out by the panel\'s scheduler, so <code>php artisan schedule:run</code> has to be running every minute on this box. Without it a due date simply passes and nothing happens.', '<strong>Delete and force delete cannot be undone.</strong> Both remove the server, its databases and its files. Suspension is the safe choice: the server stops and its owner loses access, but nothing is destroyed and an administrator can reverse it.', 'A due date is set on the admin <em>create server</em> form and on any existing server\'s <em>Manage</em> page. Turning this addon off hides both and stops the scheduler acting, but it does not throw away the dates already set, and turning it back on resumes them.', ], ]; /* 1791839714 */ private const LABELS = [ 'switch_startup' => [ 'label' => 'Startup command on a switch', 'choices' => ['' => 'Always replace it', '0' => 'Customer chooses'], 'help' => 'Replacing gives every switched server the new egg\'s startup command. Customer chooses adds a box to the switch dialog so they can keep the one they have.', ], 'switch_reinstall' => [ 'label' => 'Reinstall after a switch', 'choices' => ['' => 'Always reinstall', '0' => 'Customer chooses'], 'help' => 'Always runs the new egg\'s install script straight after the switch. Customer chooses lets them change egg without reinstalling, which leaves every file as it was.', ], 'switch_wipe' => [ 'label' => 'Clear files before reinstalling', 'choices' => ['' => 'Customer chooses', '1' => 'Always clear them'], 'help' => 'Customer chooses offers it as a box in the switch dialog, and only to people allowed to delete files. Always empties the server before every reinstall. Nothing is cleared when a switch skips the reinstall.', ], 'admin_hints' => [ 'label' => 'Field descriptions', 'choices' => AdminTheme::HINTS, 'help' => 'Where the line of explanation under a field goes, across every admin page. Beside the label keeps forms short and opens on hover, focus or a tap; the text is the same either way.', ], 'admin_mode' => [ 'label' => 'Light and dark', 'choices' => AdminTheme::MODES, 'help' => 'Same as the client panel follows the Light and dark setting in the theme editor: a mode pinned there is pinned here too, and otherwise each admin gets the switch, opening in whichever mode they last picked on either side. Pinning a mode here hides the switch for everybody.', ], 'retention_days' => [ 'label' => 'Days to keep deleted files', 'placeholder' => '7', 'help' => 'How long something stays in the bin before it is deleted for real. Empty or zero means 7 days, and 365 is the most it will take. The figure is written onto each file as it is deleted, so shortening this never destroys something a person was already told they had longer to recover.', ], 'curseforge_key' => [ 'label' => 'CurseForge API key', 'placeholder' => '$2a$10$…', 'help' => 'Without one, CurseForge is simply absent from the source tabs rather than present and broken. Get a key at <a href="https://console.curseforge.com/" target="_blank" rel="noreferrer">console.curseforge.com</a>. It is stored on the panel and never sent to a browser. A <code>CURSEFORGE_KEY</code> in <code>.env</code> wins over this field.', ], 'curseforge_base' => [ 'label' => 'CurseForge API base URL', 'placeholder' => 'https://api.curseforge.com', 'help' => 'Leave empty unless the panel cannot reach CurseForge directly. Their API sits behind CloudFront, which answers a refused request with the same 403 whatever the reason. Point this at a proxy you control if that happens.', ], 'google_client_id' => [ 'label' => 'Google OAuth client ID', 'placeholder' => '…apps.googleusercontent.com', 'help' => 'Create an OAuth 2.0 Web application client in <a href="https://console.cloud.google.com/apis/credentials" target="_blank" rel="noreferrer">Google Cloud</a> with the Drive API enabled, and add this panel\'s callback as an authorised redirect URI.', ], 'hytale_directory' => [ 'label' => 'Mod folder', 'placeholder' => 'mods', 'help' => 'Relative to the server root. A guess until Hytale publishes its server layout. Anything trying to climb out of the server root is ignored and the default used instead.', ], 'hytale_extensions' => [ 'label' => 'Mod file extensions', 'placeholder' => '.jar,.zip,.hymod', 'help' => 'Comma separated. Only files ending in one of these are listed, installed or removed by the tab, and everything else in the folder is left alone. A bare <code>jar</code> and <code>.jar</code> mean the same thing.', ], 'palworld_directory' => [ 'label' => 'Mod folder', 'placeholder' => 'Pal/Content/Paks/~mods', 'help' => 'Relative to the server root. <code>Pal/Content/Paks/~mods</code> is where Unreal picks up loose pak mods; some setups use <code>Pal/Content/Paks/LogicMods</code> instead. Anything trying to climb out of the server root is ignored and the default used.', ], 'palworld_extensions' => [ 'label' => 'Mod file extensions', 'placeholder' => '.pak,.ucas,.utoc,.zip,.dll,.lua', 'help' => 'Comma separated. Only files ending in one of these are listed, installed, unpacked or removed by the tab, and everything else in the folder is left alone. A bare <code>pak</code> and <code>.pak</code> mean the same thing.', ], 'default_action' => [ 'label' => 'What a due date does by default', 'choices' => \Pterodactyl\Services\Dezerx\AutoAction\AutoActions::ACTIONS, 'help' => 'Only the value the two forms open on. Whoever sets the date picks the action, and this is simply what is already selected for them.', ], 'default_term_days' => [ 'label' => 'Default term, in days', 'placeholder' => '30', 'help' => 'Prefills the due date on the create-server form with this many days from now, so a host selling a monthly plan types nothing. Leave empty and the field opens blank, which means no auto action unless one is typed in.', ], 'grace_minutes' => [ 'label' => 'Grace period, in minutes', 'placeholder' => '0', 'help' => 'How long after the due date the panel waits before acting. Useful when payment reminders go out on the hour and you would rather not race them. Zero acts on the next scheduler tick after the date passes.', ], 'block_vpn' => [ 'label' => 'Turn away VPNs and proxies', 'choices' => ['' => 'No', '1' => 'Yes'], 'help' => 'Asks proxycheck.io about the address somebody is signing up from and refuses the ones it calls a proxy: VPNs, Tor, open proxies. Datacentre addresses are the switch below, not this one. If proxycheck cannot be reached the sign-up is allowed through, because an outage on somebody else\'s API is not a reason to stop taking accounts.', ], 'block_hosting' => [ 'label' => 'Turn away hosting and datacentre addresses', 'choices' => ['' => 'No', '1' => 'Yes'], 'help' => 'The addresses servers live at rather than people. Catches somebody signing up from a box they rent, which is most of what gets past a VPN check. Turn it off if your own users legitimately arrive this way.', ], 'duplicate_ip' => [ 'label' => 'One account per connection', 'choices' => ['' => 'No', '1' => 'Yes'], 'help' => 'Refuses a sign-up from an address another account has already been seen at. Addresses are recorded on sign-up and on every sign-in, so this only knows about accounts that have used the panel since this addon was installed. Households and offices share one address, so expect to hear from people who are not the person you meant to stop.', ], 'proxycheck_key' => [ 'label' => 'proxycheck.io API key', 'placeholder' => '123456-789012-345678-901234', 'help' => 'Optional. Without a key proxycheck answers a hundred addresses a day from this panel\'s own address, which is enough for a small panel and not for a busy one. Get one at <a href="https://proxycheck.io/" target="_blank" rel="noreferrer">proxycheck.io</a>. Every answer is kept for a day, so a returning address costs nothing.', ], 'ip_allowlist' => [ 'label' => 'Addresses that skip every check', 'placeholder' => '203.0.113.7, 198.51.100.4', 'help' => 'Comma separated. Nothing above applies to these, which is how you keep your own connection working while you are testing. Private and loopback addresses are already exempt, so a panel behind a proxy that forgets to pass the real address through fails open rather than locking everybody out.', ], 'steam_api_key' => [ 'label' => 'Steam Web API key', 'placeholder' => 'A1B2C3D4E5F6…', 'help' => 'Optional. Makes Workshop search and required items come from Steam\'s API instead of its web pages. Get one at <a href="https://steamcommunity.com/dev/apikey" target="_blank" rel="noreferrer">steamcommunity.com/dev/apikey</a>. It is stored on the panel and never sent to a browser.', ], 'google_client_secret' => [ 'label' => 'Google OAuth client secret', 'placeholder' => 'GOCSPX-…', 'help' => 'Stored on the panel and never sent to a browser. Without both halves the Drive card tells the server owner to ask an administrator rather than showing a button that cannot work.', ], ]; private const EXTRA_TITLES = [ Addons::EGG_SWITCHER => 'Switch behaviour', Addons::ADMIN_THEME => 'Mode', Addons::SECURITY => 'What is turned away', Addons::AUTO_ACTION => 'Defaults', Addons::PALWORLD_MOD_MANAGER => 'Where the mods live', Addons::HYTALE_MOD_MANAGER => 'Where the mods live', Addons::DAYZ_MOD_MANAGER => 'Steam', ]; private function setup(string $addon): array { if ($addon !== Addons::DRIVE_BACKUPS) { return []; } return [ [ 'title' => 'Turn the Drive API on', 'body' => 'In <a href="https://console.cloud.google.com/apis/library/drive.googleapis.com" target="_blank" rel="noreferrer">Google Cloud</a>, pick or create a project and enable the Google Drive API for it. Nothing below works until this is done.', 'fields' => [], ], [ 'title' => 'Set the consent screen up', 'body' => 'Under APIs and services, OAuth consent screen. External is the right type unless everyone using this panel is in your own Google Workspace. Add <code>' . GoogleDrive::SCOPE . '</code> as a scope, which reaches only files this panel creates and nothing else in anybody\'s Drive. While the app is in Testing, only accounts you list as test users can connect, so publish it when you are ready for customers to use it.', 'fields' => [], ], [ 'title' => 'Create the OAuth client', 'body' => 'Credentials, Create credentials, OAuth client ID, and pick <strong>Web application</strong>. Then paste these two in, exactly as they appear:', 'fields' => [ [ 'label' => 'Authorised JavaScript origins', 'value' => '', 'note' => 'Leave this empty. It is for flows where a page talks to Google from the browser, and this one does not: the panel redirects, Google redirects back, and the token exchange happens server to server. If the form will not let you save it empty, put ' . rtrim(config('app.url'), '/') . ' in.', ], [ 'label' => 'Authorised redirect URIs', 'value' => route('dezerx.drive.callback'), 'note' => 'Exactly this, with no trailing slash. Google matches it character for character and answers redirect_uri_mismatch if it differs by so much as http instead of https.', ], ], ], [ 'title' => 'Copy the two halves in below', 'body' => 'Google shows the client ID and secret once the client is made. Both go in the Credentials box on this page. Google says changes can take a few minutes to a few hours to take effect, so a redirect_uri_mismatch straight after saving is usually just that.', 'fields' => [], ], ]; } public function __construct(private AlertsMessageBag $alert) { } public function index(): View { return view('admin.dezerx.addons.index', [ 'catalogue' => Addons::CATALOGUE, 'addons' => Addons::all(), ]); } public function show(string $addon): View|RedirectResponse { if ($addon === Addons::DISCORD_BOT) { return redirect()->route('admin.dezerx.discordbot'); } $meta = $this->meta($addon); $config = Addons::get($addon); $pickers = Addons::isGlobal($addon) ? [] : [[ 'name' => 'eggs[]', 'label' => (Addons::EGG_LISTS[$addon] ?? []) === [] ? 'Eggs' : 'Eggs this tab appears on', 'help' => null, 'selected' => $config['eggs'], ]]; foreach (Addons::isGlobal($addon) ? [] : (Addons::EGG_LISTS[$addon] ?? []) as $list => $listMeta) { $pickers[] = [ 'name' => 'lists[' . $list . '][]', 'label' => $listMeta['label'], 'help' => $listMeta['help'], 'selected' => (array) ($config[$list] ?? []), ]; } return view('admin.dezerx.addons.manage', [ 'pickers' => $pickers, 'scoped' => !Addons::isGlobal($addon), 'extrasTitle' => self::EXTRA_TITLES[$addon] ?? 'Credentials', 'key' => $addon, 'meta' => $meta, 'notes' => self::NOTES[$addon] ?? [], 'config' => $config, 'extras' => Addons::EXTRAS[$addon] ?? [], 'labels' => self::LABELS, 'setup' => $this->setup($addon), 'nests' => Nest::query()->with('eggs')->orderBy('name')->get(), 'eggRules' => $addon === Addons::EGG_SWITCHER ? \Pterodactyl\Services\Dezerx\EggRules::all() : null, ]); } public function update(Request $request, string $addon): RedirectResponse { $meta = $this->meta($addon); $data = $request->validate([ 'enabled' => ['sometimes', 'boolean'], 'eggs' => ['sometimes', 'array'], 'eggs.*' => ['string'], 'extras' => ['sometimes', 'array'], 'extras.*' => ['nullable', 'string', 'max:255'], 'lists' => ['sometimes', 'array'], 'lists.*' => ['array'], 'lists.*.*' => ['string'], ]); $extras = []; foreach (Addons::EXTRAS[$addon] ?? [] as $extra) { if (array_key_exists($extra, $data['extras'] ?? [])) { $extras[$extra] = (string) ($data['extras'][$extra] ?? ''); } } $lists = []; foreach (array_keys(Addons::EGG_LISTS[$addon] ?? []) as $list) { if (array_key_exists($list, $data['lists'] ?? [])) { $lists[$list] = (array) $data['lists'][$list]; } else { $lists[$list] = []; } } Addons::save( $addon, (bool) ($data['enabled'] ?? false), $data['eggs'] ?? [], $extras, $lists, ); $this->alert->success($meta['name'] . ' settings have been updated.')->flash(); return redirect()->route('admin.dezerx.addons.show', $addon); } private function meta(string $addon): array { return Addons::CATALOGUE[$addon] ?? throw new NotFoundHttpException(); } } 